function updateKeyboardCamera(time){
  const delta=lastCameraFrame?Math.min((time-lastCameraFrame)/1000,.05):1/60;
  lastCameraFrame=time;
  let forwardAmount=Number(cameraKeys.has('w'))+Number(cameraKeys.has('arrowup'))-Number(cameraKeys.has('s'))-Number(cameraKeys.has('arrowdown'));
  let rightAmount=Number(cameraKeys.has('d'))+Number(cameraKeys.has('arrowright'))-Number(cameraKeys.has('a'))-Number(cameraKeys.has('arrowleft'));
  let verticalAmount=cameraMode==='free'?Number(cameraKeys.has('e'))-Number(cameraKeys.has('q')):0;
  const horizontal=forwardAmount!==0||rightAmount!==0,vertical=verticalAmount!==0;
  targetCameraVelocity.set(0,0,0);
  if(horizontal||vertical){
    const magnitude=Math.hypot(forwardAmount,rightAmount,verticalAmount);
    forwardAmount/=magnitude;rightAmount/=magnitude;verticalAmount/=magnitude;
    cam.updateMatrixWorld(true);
    const forward=cam.getWorldDirection(new THREE.Vector3());
    forward.y=0;
    if(forward.lengthSq()<.0001)forward.set(-Math.sin(th),0,-Math.cos(th));
    forward.normalize();
    const right=new THREE.Vector3(1,0,0).applyQuaternion(cam.quaternion);
    right.y=0;right.normalize();
    targetCameraVelocity.copy(forward).multiplyScalar(forwardAmount).addScaledVector(right,rightAmount);
    targetCameraVelocity.y=verticalAmount;
    targetCameraVelocity.multiplyScalar(5.5);
  }
  cameraVelocity.lerp(targetCameraVelocity,1-Math.exp(-13*delta));
  if(cameraVelocity.lengthSq()>.0001){
    const position=cameraMode==='free'?freeCameraPosition:camTarget;
    position.addScaledVector(cameraVelocity,delta);
    updCam();
    cameraNeedsSave=true;
    if(time-lastCameraSave>600){lastCameraSave=time;persistCamera()}
  }else if(cameraNeedsSave){cameraNeedsSave=false;persistCamera()}
}
